-- GenDB engine variant Q08-between_expansion: template q08.sql, kind between_expansion (generated by generate.py; frozen)
SELECT
  o_year,
  SUM(CASE WHEN nation = $1 THEN volume ELSE 0 END) / SUM(volume) AS mkt_share
FROM (
  SELECT
    EXTRACT(YEAR FROM o_orderdate) AS o_year,
    l_extendedprice * (
      1 - l_discount
    ) AS volume,
    n2.n_name AS nation
  FROM part, supplier, lineitem, orders, customer, nation AS n1, nation AS n2, region
  WHERE
    p_partkey = l_partkey
    AND s_suppkey = l_suppkey
    AND l_orderkey = o_orderkey
    AND o_custkey = c_custkey
    AND c_nationkey = n1.n_nationkey
    AND n1.n_regionkey = r_regionkey
    AND r_name = $2
    AND s_nationkey = n2.n_nationkey
    AND o_orderdate >= CAST('1995-01-01' AS DATE)
    AND o_orderdate <= CAST('1996-12-31' AS DATE)
    AND p_type = $3
) AS all_nations
GROUP BY
  o_year
ORDER BY
  o_year
